      "kind": "effect",
      "type": "ascii",
      "name": "ASCII",
      "opacity": 1,
      "visible": true,
      "params": {
        "input": "luminance",
        "columns": 155,
        "charset": "light",
        "customChars": " .:-=+*#%@",
        "fontFamily": "mono",
        "fontWeight": 400,
        "boldness": 0,
        "colorMode": "monochrome",
        "monoColor": "#f5f5f0",
        "bgOpacity": 0,
        "signalBlackPoint": 0,
        "signalWhitePoint": 0.04,
        "invert": false,
        "breakGrid": "off",
        "breakThreshold": 0.06,
        "rowWarp": 0
      }
